// Embeds the built runtime bundles (packages/runtime/dist) as base64 strings in src/runtime-bundles.generated.ts, so
// the Trigger.dev bundle carries them without a build extension. Run after `pnpm build`, before `trigger.dev dev` or
// `deploy`. The generated file is git-ignored.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const dist = path.resolve(here, "../../../packages/runtime/dist");
const read = (name) => readFileSync(path.join(dist, name)).toString("base64");

const out = [
  "// Generated by prepare.mjs from packages/runtime/dist. Do not edit.",
  `export const runtime = "${read("selfbuilding-runtime.mjs")}";`,
  `export const mcp = "${read("selfbuilding-mcp.mjs")}";`,
  `export const nsReap = "${read("ns-reap.mjs")}";`,
  "",
].join("\n");
writeFileSync(path.join(here, "src/runtime-bundles.generated.ts"), out);
console.log("wrote src/runtime-bundles.generated.ts");
